cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry input validation', () => {
  it('returns a rejection naming location as required and never calls the executor when input is empty', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/location.*required|required.*location/i),
    });
  });
});
EOF
timeout 300 npm test -- src/orchestration/tools/registry.test.ts 2>&1 | grep -E 'Tests:|Expected|Received|●' | head

